using System;using System.Linq;using System.Runtime.CompilerServices;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class TopTabLayout {
 static readonly ConditionalWeakTable<Control,object> hooked=new ConditionalWeakTable<Control,object>();
 internal static void AttachCommands(TabControl root,Control commands,Form owner){Action move=null;Action<Control> hook=null;move=()=>{if(root.IsDisposed||root.SelectedTab==null)return;TabPage page=root.SelectedTab;for(;;){var nested=page.Controls.OfType<TabControl>().FirstOrDefault();if(nested==null||nested.SelectedTab==null)break;page=nested.SelectedTab;}if(commands.Parent!=page)page.Controls.Add(commands);commands.Dock=DockStyle.Top;page.Controls.SetChildIndex(commands,page.Controls.Count-1);};hook=control=>{object old;if(hooked.TryGetValue(control,out old))return;hooked.Add(control,new object());var tabs=control as TabControl;if(tabs!=null){ModernUi.Navigation(tabs);tabs.SelectedIndexChanged+=(s,e)=>move();}foreach(Control child in control.Controls)hook(child);control.ControlAdded+=(s,e)=>hook(e.Control);};hook(root);owner.Shown+=(s,e)=>move();move();}
 internal static void Promote(Form owner,TabControl tabs,Control input,Control oldHost,Control commands,string caption,Control note=null){owner.SuspendLayout();try{if(oldHost!=null&&oldHost!=tabs){oldHost.Controls.Remove(tabs);owner.Controls.Remove(oldHost);oldHost.Dispose();}else owner.Controls.Remove(tabs);owner.Controls.Remove(input);var page=new TabPage(caption);input.Dock=DockStyle.Fill;page.Controls.Add(input);if(note!=null){owner.Controls.Remove(note);note.Dock=DockStyle.Top;page.Controls.Add(note);}tabs.TabPages.Insert(0,page);tabs.Dock=DockStyle.Fill;owner.Controls.Add(tabs);owner.Controls.SetChildIndex(tabs,0);tabs.SelectedTab=page;AttachCommands(tabs,commands,owner);}finally{owner.ResumeLayout(true);}}
}
}
